<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:12px}h1{font-size:26px;margin:0}.muted{color:#64748b}table{width:100%;border-collapse:collapse;margin-top:20px}td{padding:10px;border-bottom:1px solid #dbe3ef}.right{text-align:right}.amount{font-size:20px;font-weight:bold;color:#087443}</style></head><body><h1>StayTrack</h1><p class="muted">Apartment Management · Receipt #{{ $payment->id }}</p><p class="amount">Payment received: ₱{{ number_format($payment->amount_paid, 2) }}</p><table><tr><td><strong>Tenant</strong><br>{{ $payment->bill->lease->tenant->full_name }}</td><td><strong>Apartment</strong><br>Unit {{ $payment->bill->lease->apartment->unit_number }}</td></tr><tr><td><strong>Payment date</strong><br>{{ $payment->payment_date?->format('M d, Y') }}</td><td><strong>Method</strong><br>{{ ucwords(str_replace('_', ' ', $payment->payment_method)) }}</td></tr><tr><td><strong>Reference number</strong><br>{{ $payment->reference_number ?: '—' }}</td><td><strong>Related bill</strong><br>{{ $payment->bill->billing_month?->format('F Y') }}</td></tr><tr><td><strong>Status</strong><br>Verified</td><td><strong>Remaining balance</strong><br>₱{{ number_format($balance, 2) }}</td></tr></table></body></html>
